solutionCode:
export function classificar(n) {
  let rotulo = 'zero';
  if (n > 0) {
    rotulo = 'positivo';
  } else if (n < 0) {
    rotulo = 'negativo';
  }
  const dobro = n * 2;
  const metade = n / 2;
  const resto = n % 2;
  const soma = n + 1;
  const diferenca = n - 1;
  const potencia = n ** 2;
  const deslocado = (n | 0) << 1;
  const mascarado = (n & 3) >> 1;
  const invertido = ~n;
  const ouExclusivo = n ^ 1;
  const ehPar = resto === 0;
  const naoEhPar = resto !== 0;
  const talvez = n ?? 0;
  const ambos = ehPar && naoEhPar;
  const qualquer = ehPar || naoEhPar;
  const negado = !ehPar;
  const tipo = typeof n;
  const ternario = ehPar ? 'par' : 'impar';
  const grande = n >= 10;
  const pequeno = n <= 1;
  const cresce = -n;
  const positivo = +n;
  return {
    rotulo, dobro, metade, soma, diferenca, potencia, deslocado, mascarado,
    invertido, ouExclusivo, ehPar, naoEhPar, talvez, ambos, qualquer, negado,
    tipo, ternario, grande, pequeno, cresce, positivo,
  };
}

testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { classificar } from './solution.mjs';

test('classifica positivo', () => {
  assert.equal(classificar(1).rotulo, 'positivo');
  assert.ok(classificar(1).ehPar === false);
  assert.deepEqual(Object.keys(classificar(0)).length > 0, true);
});
